from fractions import Fraction
def solve(params):
    level=params["level_order"]
    delete_key=params["delete_key"]
    def make_node(v):
        return {"val": v, "left": None, "right": None}
    def build(arr):
        if not arr or arr[0] is None:
            return None
        nodes=[None if v is None else make_node(v) for v in arr]
        root=nodes[0]
        q=[root]
        qi=0
        idx=1
        while qi < len(q) and idx < len(nodes):
            cur=q[qi]
            qi+=1
            if cur is None:
                continue
            if idx < len(nodes):
                cur["left"]=nodes[idx]
                q.append(nodes[idx])
                idx+=1
            if idx < len(nodes):
                cur["right"]=nodes[idx]
                q.append(nodes[idx])
                idx+=1
        return root
    def find_min(n):
        while n and n["left"]:
            n=n["left"]
        return n
    def delete_node(root,key):
        if root is None:
            return None
        if key < root["val"]:
            root["left"]=delete_node(root["left"],key)
        elif key > root["val"]:
            root["right"]=delete_node(root["right"],key)
        else:
            if root["left"] is None:
                return root["right"]
            if root["right"] is None:
                return root["left"]
            succ=find_min(root["right"])
            root["val"]=succ["val"]
            root["right"]=delete_node(root["right"],succ["val"])
        return root
    def successor_of_two_child(root,key):
        cur=root
        while cur:
            if key < cur["val"]:
                cur=cur["left"]
            elif key > cur["val"]:
                cur=cur["right"]
            else:
                break
        if cur and cur["left"] and cur["right"]:
            return find_min(cur["right"])["val"]
        return None
    def postorder(n,out):
        if n is None:
            return
        postorder(n["left"],out)
        postorder(n["right"],out)
        out.append(n["val"])
    root=build(level)
    succ_val=successor_of_two_child(root,delete_key)
    root_after=delete_node(root,delete_key)
    res=[]
    postorder(root_after,res)
    steps={}
    if succ_val is not None:
        steps["successor_key"]=succ_val
    else:
        steps["successor_key"]=root_after["val"] if root_after else None
    steps["root_value_after_deletion"]=root_after["val"] if root_after else None
    return {"answer": res, "steps": steps}
